  _q('ss-039', 's9-tar-05', 'Yazı', _k, "Günümüzde kullanılan Latin alfabesinin temelini oluşturan alfabeyi geliştiren uygarlık hangisidir?",
      ["Sümerler", "Mısırlılar", "Hititler", "Fenikeliler", "Persler"], 'D',
      "Fenikeliler harf yazısını (alfabe) geliştirmiş; bu alfabe Yunanlılar ve Romalılar aracılığıyla Latin alfabesine dönüşmüştür."),
  _q('ss-040', 's9-tar-05', 'Bilim ve Sanat', _o, "Aşağıdakilerden hangisi Mezopotamya uygarlıklarının bilim alanındaki katkılarından biri değildir?",
      ["Ay yılı esaslı takvim", "Dört işlem ve altmışlık sayı sistemi", "Çivi yazısı", "Güneş ve Ay tutulmalarının hesaplanması", "Güneş yılı esaslı takvim"], 'E',
      "Güneş yılı esaslı takvimi Mısırlılar geliştirmiştir; Mezopotamya'da Ay yılı esaslı takvim kullanılmıştır."),
  _q('ss-041', 's9-tar-07', 'Kavimler Göçü', _k, "375 yılında Hunların batıya ilerlemesiyle başlayan ve Avrupa'nın etnik yapısını değiştiren olay aşağıdakilerden hangisidir?",
