  _q('ss-078', 's10-edb-01', 'Koşuk', _k, "İslamiyet öncesi Türk şiirinde doğa, aşk ve kahramanlık konularını işleyen, sığır törenlerinde söylenen şiirlere ne ad verilir?",
      ["Sagu", "Sav", "Koşuk", "Destan", "Koşma"], 'C',
      "Koşuk; av törenlerinde (sığır) söylenen, doğa ve aşk temalı şiirdir. Halk edebiyatındaki koşmanın ilk biçimi sayılır."),
  _q('ss-079', 's10-edb-01', 'Sagu', _k, "İslamiyet öncesi Türk edebiyatında “yuğ” adı verilen yas törenlerinde söylenen ağıt şiirlerine ne denir?",
      ["Koşuk", "Sav", "Destan", "Sagu", "Semai"], 'D',
      "Sagu, ölen kişinin ardından yuğ törenlerinde söylenen ağıttır. En bilinen örneği Alp Er Tunga sagusudur."),
  _q('ss-080', 's10-edb-01', 'Sözlü Dönem', _o, "İslamiyet öncesi Türk şiirinin özelliklerinden biri aşağıdakilerden hangisi değildir?",
      ["Hece ölçüsüyle söylenmesi", "Nazım biriminin dörtlük olması", "Kopuz eşliğinde söylenmesi", "Yarım uyağın kullanılması", "Aruz ölçüsünün kullanılması"], 'E',
      "Aruz ölçüsü İslamiyet'in kabulünden sonra Arap ve Fars edebiyatından alınmıştır. Sözlü dönem şiirinde hece ölçüsü ve dörtlük kullanılır."),
  _q('ss-081', 's10-edb-04', 'Saf Şiir', _k, "“Şiir, şiir içindir.” anlayışını benimseyen; dil, ahenk ve biçim kusursuzluğunu öne çıkaran şiir anlayışı hangisidir?",
      ["Toplumcu gerçekçi şiir", "Saf (öz) şiir", "Garip şiiri", "Destan şiiri", "Didaktik şiir"], 'B',
      "Saf şiir anlayışında amaç bir düşünceyi öğretmek değil, güzel ve ahenkli şiir yazmaktır; sembolizmden etkilenmiştir."),
  _q('ss-082', 's10-edb-04', 'Temsilciler', _o, "Aşağıdaki şairlerden hangisi saf şiir anlayışının temsilcilerinden biridir?",
      ["Ahmet Haşim", "Nâzım Hikmet", "Orhan Veli Kanık", "Mehmet Âkif Ersoy", "Tevfik Fikret"], 'A',
      "Ahmet Haşim, Yahya Kemal Beyatlı, Ahmet Hamdi Tanpınar ve Necip Fazıl Kısakürek saf şiir anlayışının önemli adlarıdır."),
  _q('ss-083', 's10-edb-04', 'Saf Şiirin Özellikleri', _o, "Saf şiirle ilgili aşağıdaki ifadelerden hangisi yanlıştır?",
      ["Ahenk ve musiki önemsenir.", "İmge ve çağrışıma yer verilir.", "Şiirin temel amacı toplumu bilgilendirmek ve yönlendirmektir.", "Biçim kusursuzluğuna önem verilir.", "Bireysel temalar işlenir."], 'C',
      "Saf şiirde didaktik amaç güdülmez; şiir bir sanat ürünü olarak görülür. Toplumu yönlendirme amacı toplumcu şiirin özelliğidir."),
  _q('ss-084', 's10-edb-04', 'Temsilciler', _z, "“Sessiz Gemi”, “Rindlerin Akşamı” gibi şiirleriyle tanınan; şiirde ahenk ve söyleyiş mükemmelliğine önem veren şair kimdir?",
      ["Ahmet Haşim", "Cahit Sıtkı Tarancı", "Necip Fazıl Kısakürek", "Yahya Kemal Beyatlı", "Ahmet Muhip Dıranas"], 'D',
      "Yahya Kemal Beyatlı aruz ölçüsünü Türkçeye ustalıkla uygulamış; “Kendi Gök Kubbemiz” adlı kitabındaki şiirlerde saf şiirin en güzel örneklerini vermiştir."),
  _q('ss-085', 's10-edb-05', 'Destan', _k, "Aşağıdakilerden hangisi doğal (sözlü gelenekten gelen) destanların özelliklerinden biridir?",
      ["Yazarının belli olması", "Yakın zamanda yazılmış olması", "Bireysel konuları işlemesi", "Kısa ve tek olaylı olması", "Olağanüstü olay ve kişilere yer vermesi"], 'E',
      "Doğal destanlar anonimdir, milletlerin hayatını derinden etkileyen olayları anlatır ve olağanüstülükler içerir."),
  _q('ss-086', 's10-edb-05', 'Türk Destanları', _o, "Aşağıdaki destanlardan hangisi Göktürklere aittir?",
      ["Oğuz Kağan Destanı", "Ergenekon Destanı", "Alp Er Tunga Destanı", "Türeyiş Destanı", "Manas Destanı"], 'B',
      "Ergenekon ve Bozkurt destanları Göktürklere; Oğuz Kağan Hunlara; Alp Er Tunga ve Şu Sakalara; Türeyiş ve Göç Uygurlara; Manas Kırgızlara aittir."),
  _q('ss-087', 's10-edb-05', 'Halk Hikâyesi', _o, "Halk hikâyelerini destandan ayıran özelliklerden biri aşağıdakilerden hangisidir?",
      ["Nazım-nesir karışık olması ve olağanüstülüklerin azalması", "Anonim olması", "Sözlü gelenekte oluşması", "Kahramanlık konusunu işleyebilmesi", "Kuşaktan kuşağa aktarılması"], 'A',
      "Halk hikâyeleri destandan modern hikâyeye geçiş ürünüdür; nazım ve nesir karışıktır, olağanüstü ögeler azalmış, aşk konusu öne çıkmıştır."),
  _q('ss-088', 's10-edb-06', 'Mesnevi', _o, "Mesnevi nazım biçimiyle ilgili aşağıdakilerden hangisi doğrudur?",
      ["Dörtlüklerle yazılır.", "Hece ölçüsü kullanılır.", "Her beyit kendi içinde uyaklıdır (aa, bb, cc…).", "En çok on beş beyit olabilir.", "Yalnızca dinî konular işlenir."], 'C',
      "Mesnevide her beyit kendi arasında uyaklıdır; bu nedenle beyit sayısı sınırsızdır ve uzun hikâyeler anlatmaya elverişlidir."),
  _q('ss-089', 's10-edb-07', 'Dede Korkut', _k, "Dede Korkut Hikâyeleri toplam kaç hikâyeden oluşur?",
      ["Yedi hikâye", "On hikâye", "Yirmi dört hikâye", "Bir ön söz ve on iki hikâye", "Otuz hikâye"], 'D',
      "Dresden nüshasında bir ön söz ve on iki hikâye bulunur. Son yıllarda bulunan yeni nüshayla bir hikâye daha eklenmiştir."),
  _q('ss-090', 's10-edb-07', 'Dede Korkut', _o, "Dede Korkut Hikâyeleri'nin Türk edebiyatındaki yeri için aşağıdakilerden hangisi söylenebilir?",
      ["İlk yerli romandır.", "İlk edebî romandır.", "İlk tiyatro eseridir.", "İlk köy romanıdır.", "Destandan halk hikâyesine geçiş dönemi ürünüdür."], 'E',
      "Dede Korkut Hikâyeleri destan özellikleriyle halk hikâyesi özelliklerini bir arada taşır; nazım ve nesir karışıktır."),
  _q('ss-091', 's10-edb-07', 'Dede Korkut', _o, "Dede Korkut Hikâyeleri'nde aşağıdaki konulardan hangisi işlenmez?",
      ["Oğuz boylarının iç mücadeleleri", "Sanayileşme ve şehir yaşamı", "Düşmanlarla yapılan savaşlar", "Aile, çocuk sevgisi ve kahramanlık", "Olağanüstü varlıklarla mücadele"], 'B',
      "Hikâyeler Oğuzların konargöçer yaşamını, kahramanlıklarını, aile ve töre anlayışını anlatır."),
  _q('ss-092', 's10-edb-07', 'Dede Korkut', _z, "Dede Korkut Hikâyeleri'nde Dede Korkut'un işlevi aşağıdakilerden hangisidir?",
      ["Hikâyelerin sonunda gelip dua eden, ad koyan bilge kişi ve ozan olması", "Savaşlarda orduya komuta etmesi", "Oğuzların düşmanı olması", "Hikâyelerin baş kahramanı olması", "Yalnızca ön sözde adının geçmesi"], 'A',
      "Dede Korkut bilge bir ozandır; gençlere ad verir, sorunları çözer ve her hikâyenin sonunda kopuz çalıp dua eder."),
  // ═══ 10. SINIF TARİH ════════════════════════════════════════════════
  _q('ss-093', 's10-tar-02', 'Devlet Teşkilatı', _k, "Büyük Selçuklu Devleti'nde devlet işlerinin görüşülüp karara bağlandığı büyük divana ne ad verilir?",
      ["Divan-ı Hümayun", "Kurultay", "Divan-ı Saltanat (Divan-ı Âlâ)", "Meclis-i Mebusan", "Pankuş"], 'C',
      "Selçuklularda devlet işleri vezirin başkanlığındaki Divan-ı Saltanat'ta (Divan-ı Âlâ) görüşülürdü. Divan-ı Hümayun Osmanlı'ya aittir."),
  _q('ss-094', 's10-tar-02', 'Toprak Sistemi', _o, "Büyük Selçuklu Devleti'nde toprak gelirlerinin hizmet karşılığında asker ve devlet görevlilerine bırakılması sistemine ne ad verilir?",
      ["Tımar", "Malikâne", "Vakıf", "İkta", "Mülk"], 'D',
      "İkta sistemiyle devlet, hazineden para çıkmadan ordu beslemiş ve üretimin sürekliliğini sağlamıştır. Osmanlı'daki tımar sisteminin temelidir."),
  _q('ss-095', 's10-tar-02', 'Ordu', _o, "Büyük Selçuklu ordusunda, küçük yaşta alınarak özel olarak yetiştirilen ve doğrudan sultana bağlı olan askerlere ne ad verilir?",
      ["Sipahiler", "Türkmenler", "Azaplar", "Akıncılar", "Gulaman-ı Saray (Gulam askerleri)"], 'E',
      "Gulam sistemiyle farklı milletlerden alınan çocuklar özel eğitimden geçirilerek saray ve ordu hizmetine alınırdı."),
  _q('ss-096', 's10-tar-02', 'Devlet Anlayışı', _o, "Türk-İslam devletlerinde “ülke hanedanın ortak malıdır” anlayışının en önemli sonucu aşağıdakilerden hangisidir?",
      ["Devletin sınırlarının genişlemesi", "Taht kavgalarının çıkması ve devletlerin kısa sürede parçalanması", "Ordunun güçlenmesi", "Ticaretin gelişmesi", "Halkın yönetime katılması"], 'B',
      "Bu anlayış hanedan üyeleri arasında taht kavgalarına yol açmış; merkezî otoriteyi zayıflatarak devletlerin bölünmesine neden olmuştur."),
  _q('ss-097', 's10-tar-03', 'Ekonomik Hayat', _k, "Türkiye Selçukluları döneminde esnaf ve zanaatkârların oluşturduğu, mesleki ve ahlaki dayanışma örgütü aşağıdakilerden hangisidir?",
      ["Ahilik", "Lonca", "Enderun", "Divan", "İkta"], 'A',
      "Ahi teşkilatı, Ahi Evran'ın öncülüğünde kurulmuş; üretimde kaliteyi, meslek ahlakını ve dayanışmayı sağlamıştır."),
  _q('ss-098', 's10-tar-03', 'Ekonomik Hayat', _o, "Türkiye Selçuklularının ticareti geliştirmek için aldığı önlemlerden biri aşağıdakilerden hangisi değildir?",
      ["Kervansaraylar yapılması", "Zarara uğrayan tüccarın zararının devletçe karşılanması", "Yabancı tüccarların ülkeye girişinin yasaklanması", "Sinop ve Antalya gibi limanların alınması", "Düşük gümrük vergisi uygulanması"], 'C',
      "Selçuklular yabancı tüccarları teşvik etmiş; düşük gümrük, devlet sigortası, kervansaraylar ve liman kentleriyle ticareti canlandırmıştır."),
  _q('ss-099', 's10-tar-03', 'Sosyal Hayat', _o, "Selçuklularda hem eğitim hem sağlık hizmeti veren, hastaların tedavi edildiği kurumlara ne ad verilir?",
      ["Kervansaray", "Medrese", "İmaret", "Darüşşifa", "Ribat"], 'D',
      "Darüşşifalar (bimaristan) hastane ve tıp okulu işlevi görmüştür. Kayseri'deki Gevher Nesibe Darüşşifası önemli bir örnektir."),
  _q('ss-100', 's10-tar-03', 'Sosyal Hayat', _o, "Türk-İslam devletlerinde cami, medrese, hastane gibi kurumların giderlerinin karşılanmasını sağlayan sistem aşağıdakilerden hangisidir?",
      ["İkta sistemi", "Gulam sistemi", "Tımar sistemi", "Devşirme sistemi", "Vakıf sistemi"], 'E',
      "Vakıflar, hayırseverlerin mal ve gelirlerini toplum yararına bağışladığı kurumlardır; eğitim, sağlık ve sosyal hizmetleri devlete yük olmadan yürütmüştür."),
  _q('ss-101', 's10-tar-04', 'Eğitim', _o, "Büyük Selçuklu veziri Nizamülmülk'ün devlet yönetimi hakkında yazdığı eser aşağıdakilerden hangisidir?",
      ["Kutadgu Bilig", "Siyasetname", "Divânu Lugâti't-Türk", "Atabetü'l-Hakayık", "Mesnevi"], 'B',
      "Nizamülmülk'ün Siyasetname'si devlet yönetimi ve teşkilatı hakkında bilgi verir. Kutadgu Bilig Yusuf Has Hacib'in, Divânu Lugâti't-Türk Kaşgarlı Mahmud'un eseridir."),
  _q('ss-102', 's10-tar-05', 'Kuruluş', _o, "Osmanlı Devleti'nin Rumeli'ye geçişini sağlayan ilk toprak parçası aşağıdakilerden hangisidir?",
      ["Çimpe Kalesi", "Edirne", "Selanik", "Sofya", "Gelibolu"], 'A',
      "Orhan Bey döneminde Bizans'a yapılan yardım karşılığında alınan Çimpe Kalesi (1353), Rumeli'deki ilk Osmanlı toprağıdır."),
  _q('ss-103', 's10-tar-06', 'Devletleşme', _o, "Osmanlı Devleti'nde ilk divan teşkilatının kurulması ve ilk vezirin atanması hangi padişah döneminde gerçekleşmiştir?",
      ["Osman Bey", "I. Murad", "Orhan Bey", "Yıldırım Bayezid", "Çelebi Mehmed"], 'C',
      "Orhan Bey döneminde divan kurulmuş, ilk vezir atanmış, ilk düzenli ordu (yaya ve müsellem) oluşturulmuş ve ilk medrese açılmıştır."),
  _q('ss-104', 's10-tar-06', 'Hukuk', _o, "Osmanlı hukuk sisteminde padişahın emir ve fermanlarına dayanan hukuka ne ad verilir?",
      ["Şeri hukuk", "Medeni hukuk", "Anayasa hukuku", "Örfi hukuk", "Ticaret hukuku"], 'D',
      "Osmanlı hukuku şeri ve örfi hukuk olmak üzere ikiye ayrılır. Örfi hukuk Türk töresine ve padişah fermanlarına (kanunname) dayanır."),
  _q('ss-105', 's10-tar-07', 'İskân Politikası', _k, "Osmanlı Devleti'nin fethettiği topraklara Anadolu'dan Türkmenleri yerleştirmesine ne ad verilir?",
      ["İstimalet", "Devşirme", "Müsadere", "İltizam", "İskân"], 'E',
      "İskân politikasıyla fethedilen yerler Türkleştirilmiş, fetihler kalıcı hâle getirilmiş ve konargöçerler yerleşik hayata geçirilmiştir."),
  _q('ss-106', 's10-tar-07', 'İstimalet', _o, "Osmanlı Devleti'nin fethettiği yerlerdeki gayrimüslim halka hoşgörülü ve adaletli davranması politikasına ne ad verilir?",
      ["İskân", "İstimalet", "Devşirme", "Tımar", "Kapitülasyon"], 'B',
      "İstimalet, halkın gönlünü kazanma politikasıdır; din ve vicdan özgürlüğü tanınmış, vergiler hafifletilmiştir. Bu politika Balkan fetihlerini kolaylaştırmıştır."),
  _q('ss-107', 's10-tar-07', 'Fetih Politikası', _o, "Osmanlı Devleti'nin Balkanlarda hızla ilerlemesinin nedenlerinden biri aşağıdakilerden hangisi değildir?",
      ["Balkan halklarının Osmanlı'ya karşı güçlü bir siyasi birlik oluşturması", "Bizans'ın zayıf olması", "Hoşgörülü yönetim anlayışı", "Balkanlardaki mezhep çatışmaları", "İskân politikasının uygulanması"], 'A',
      "Balkanlarda siyasi birlik yoktu; feodal beyler arasındaki mücadeleler ve mezhep çatışmaları Osmanlı ilerleyişini kolaylaştırmıştır."),
  _q('ss-108', 's10-tar-07', 'Fetih Politikası', _z, "Osmanlı Devleti'nin Anadolu Türk beyliklerine karşı genellikle savaş yerine barışçı yolları (evlilik, satın alma, miras) tercih etmesinin temel nedeni aşağıdakilerden hangisidir?",
      ["Beyliklerin çok güçlü olması", "Anadolu'nun fethe değer olmaması", "Türk ve Müslüman halkla savaşmaktan kaçınması ve Anadolu Türk birliğini kan dökmeden sağlamak istemesi", "Ordusunun bulunmaması", "Bizans'tan izin alamaması"], 'C',
      "Osmanlı, aynı kökten ve dinden olan beyliklerle savaşmayı meşru görmemiş; fetihlerini Bizans ve Balkanlara yöneltmiş, Anadolu'da ise barışçı yolları denemiştir."),
  _q('ss-109', 's10-tar-08', 'Eğitim', _k, "Osmanlı Devleti'nde ilk medrese hangi şehirde ve hangi padişah döneminde açılmıştır?",
      ["Bursa – Osman Bey", "Edirne – I. Murad", "İstanbul – II. Mehmed", "İznik – Orhan Bey", "Söğüt – Ertuğrul Gazi"], 'D',
      "İlk Osmanlı medresesi Orhan Bey döneminde İznik'te açılmış; başına Davud-ı Kayserî getirilmiştir."),
  _q('ss-110', 's10-tar-08', 'İrfan Geleneği', _o, "Osmanlı Devleti'nin kuruluşunda manevi önder olarak bilinen ve Osman Bey'in kayınpederi olan ahi şeyhi kimdir?",
      ["Hacı Bektaş Veli", "Mevlana", "Yunus Emre", "Akşemseddin", "Şeyh Edebali"], 'E',
      "Şeyh Edebali, Osman Bey'e verdiği öğütlerle tanınır; ahilerin ve dervişlerin desteği devletin kuruluşunda önemli rol oynamıştır."),
  _q('ss-111', 's10-tar-08', 'İrfan Geleneği', _o, "Osmanlı'nın kuruluş döneminde tekke ve zaviyelerin işlevlerinden biri aşağıdakilerden hangisidir?",
      ["Vergi toplamak", "Yeni fethedilen yerlerin imarına ve halkın kaynaşmasına katkı sağlamak", "Orduya komuta etmek", "Para basmak", "Dış politikayı belirlemek"], 'B',
      "Dervişler (kolonizatör dervişler) ıssız yerlerde zaviyeler kurarak bölgenin şenlenmesine, yolların güvenliğine ve kültürel kaynaşmaya katkı sağlamıştır."),
  _q('ss-112', 's10-tar-08', 'Bilim', _z, "Fatih Sultan Mehmed döneminde İstanbul'a gelerek astronomi ve matematik alanında dersler veren, Semerkant Rasathanesi'nde çalışmış bilgin kimdir?",
      ["Ali Kuşçu", "Takiyüddin", "Kâtip Çelebi", "Pîrî Reis", "Molla Lütfi"], 'A',
      "Ali Kuşçu, Uluğ Bey'in öğrencisidir; İstanbul'a gelerek Ayasofya Medresesi'nde dersler vermiş, astronomi ve matematik çalışmalarını geliştirmiştir."),
  _q('ss-113', 's10-tar-10', 'Yönetim', _k, "Osmanlı Devleti'nde devlet işlerinin görüşüldüğü, padişah ya da sadrazam başkanlığında toplanan kurul aşağıdakilerden hangisidir?",
      ["Meclis-i Mebusan", "Kurultay", "Divan-ı Hümayun", "Meclis-i Vükela", "Şûra-yı Devlet"], 'C',
      "Divan-ı Hümayun; siyasi, idari, askerî, mali ve hukuki işlerin görüşüldüğü en üst karar organıdır."),
  _q('ss-114', 's10-tar-10', 'Ordu', _o, "Osmanlı Devleti'nde Hristiyan ailelerin çocuklarının alınıp eğitilerek devlet hizmetine yetiştirilmesi sistemine ne ad verilir?",
      ["İskân", "İstimalet", "Tımar", "Devşirme", "İltizam"], 'D',
      "Devşirme sistemiyle alınan çocuklar Türk ailelerin yanında yetiştirilir; yetenekli olanlar Enderun'a, diğerleri Yeniçeri Ocağı'na alınırdı."),
  _q('ss-115', 's10-tar-10', 'Yönetimde Değişim', _o, "Fatih Sultan Mehmed'in divan toplantılarına başkanlık etmeyi bırakıp bu görevi sadrazama devretmesinin sonucu aşağıdakilerden hangisidir?",
      ["Divanın kaldırılması", "Padişahın yetkilerinin sınırlanması", "Meşrutiyetin ilan edilmesi", "Veraset sisteminin değişmesi", "Sadrazamın yönetimdeki etkisinin artması"], 'E',
      "Padişah toplantıları kafes arkasından izlemeye başlamış; divana başkanlık eden sadrazamın devlet yönetimindeki ağırlığı artmıştır."),
  _q('ss-116', 's10-tar-11', 'Coğrafi Keşifler', _k, "Coğrafi Keşiflerin Osmanlı Devleti'ne etkisi aşağıdakilerden hangisidir?",
      ["Osmanlı'nın yeni kıtalar keşfetmesi", "Akdeniz limanlarının ve İpek ile Baharat yollarının önemini yitirmesi", "Osmanlı nüfusunun azalması", "Osmanlı'nın sömürge imparatorluğu kurması", "Kapitülasyonların kaldırılması"], 'B',
      "Yeni ticaret yollarının bulunmasıyla dünya ticareti okyanuslara kaymış; Osmanlı'nın denetimindeki yollar önemini ve gümrük gelirlerini kaybetmiştir."),
  _q('ss-117', 's10-tar-11', 'Sömürgecilik', _o, "Avrupa'ya sömürgelerden bol miktarda altın ve gümüş gelmesinin Osmanlı ekonomisine etkisi aşağıdakilerden hangisidir?",
