  _q('ss-156', 's11-edb-02', 'Mektup', _o, "Türk edebiyatında mektup türüyle ilgili aşağıdaki eşleştirmelerden hangisi doğrudur?",
      ["Fuzûlî – Seyahatname", "Fuzûlî – Şikâyetname", "Evliya Çelebi – Şikâyetname", "Namık Kemal – Cihannüma", "Kâtip Çelebi – Vatan yahut Silistre"], 'B',
      "Fuzûlî, kendisine bağlanan maaşı alamayınca Nişancı Celalzade Mustafa Çelebi'ye “Şikâyetname” adlı mektubu yazmıştır."),
  _q('ss-157', 's11-edb-03', 'Türk Dünyası Edebiyatı', _k, "“Gün Olur Asra Bedel”, “Beyaz Gemi”, “Toprak Ana” gibi eserleriyle tanınan Kırgız yazar kimdir?",
      ["Cengiz Aytmatov", "Abay Kunanbayev", "Bahtiyar Vahapzade", "Cengiz Dağcı", "Muhtar Avezov"], 'A',
      "Cengiz Aytmatov, Kırgız halkının kültürünü ve insanın evrensel sorunlarını işleyen roman ve hikâyeleriyle Türk dünyası edebiyatının en tanınmış yazarıdır."),
  _q('ss-158', 's11-edb-03', 'Türk Dünyası Edebiyatı', _o, "Kırım Türklerinin yaşadığı acıları anlatan “Korkunç Yıllar”, “Onlar da İnsandı” gibi romanların yazarı kimdir?",
      ["Cengiz Aytmatov", "Resul Rıza", "Cengiz Dağcı", "Abdullah Tukay", "Mağcan Cumabayulı"], 'C',
      "Cengiz Dağcı, Kırım Tatar Türklerinin sürgün ve savaş yıllarını konu alan romanlarıyla tanınır."),
  _q('ss-159', 's11-edb-03', 'Türk Dünyası Edebiyatı', _o, "“Ana Dili” şiiriyle tanınan, Azerbaycan Türk edebiyatının önemli şairi aşağıdakilerden hangisidir?",
      ["Cengiz Aytmatov", "Abay Kunanbayev", "Mahtumkulu", "Bahtiyar Vahapzade", "Ali Şir Nevâî"], 'D',
      "Bahtiyar Vahapzade, ana dili ve bağımsızlık temalı şiirleriyle Azerbaycan edebiyatının önde gelen adlarındandır."),
  _q('ss-160', 's11-edb-03', 'Türk Dünyası Edebiyatı', _z, "Çağatay Türkçesinin en büyük şairi sayılan, “Muhâkemetü'l-Lugateyn” adlı eserinde Türkçenin Farsçadan üstün olduğunu savunan sanatçı kimdir?",
      ["Fuzûlî", "Bâkî", "Yunus Emre", "Kaşgarlı Mahmud", "Ali Şir Nevâî"], 'E',
      "Ali Şir Nevâî 15. yüzyılda Herat'ta yaşamış; Türkçe ile Farsçayı karşılaştırdığı eseriyle Türk diline büyük hizmette bulunmuştur."),
  _q('ss-161', 's11-edb-04', 'Orhun Abideleri', _o, "Orhun Abideleri'yle ilgili aşağıdaki bilgilerden hangisi yanlıştır?",
      ["Göktürk alfabesiyle yazılmıştır.", "Uygurlar döneminde dikilmiştir.", "Türk adının geçtiği ilk Türkçe metinlerdir.", "Tonyukuk, Kül Tigin ve Bilge Kağan adına dikilmiştir.", "Söylev (hitabet) türünün ilk örnekleri sayılır."], 'B',
      "Orhun Abideleri 8. yüzyılda II. Göktürk (Kutluk) Devleti döneminde dikilmiştir."),
  _q('ss-162', 's11-edb-04', 'Dîvânu Lugâti\'t-Türk', _o, "Dîvânu Lugâti't-Türk'ün yazılış amacı aşağıdakilerden hangisidir?",
      ["Araplara Türkçeyi öğretmek ve Türkçenin zenginliğini göstermek", "Devlet yönetimi hakkında öğüt vermek", "Peygamberlerin hayatını anlatmak", "Aruz ölçüsünü öğretmek", "Oğuzların destanlarını derlemek"], 'A',
      "Kaşgarlı Mahmud 11. yüzyılda yazdığı bu sözlükte Türkçe sözcükleri Arapça açıklamış; savlar, sagular ve koşuklarla Türk kültürüne ışık tutmuştur."),
  _q('ss-163', 's11-edb-05', 'Roman', _o, "Aşağıdaki yazar–eser eşleştirmelerinden hangisi yanlıştır?",
      ["Ahmet Hamdi Tanpınar – Saatleri Ayarlama Enstitüsü", "Yaşar Kemal – İnce Memed", "Oğuz Atay – Çalıkuşu", "Orhan Pamuk – Kara Kitap", "Tarık Buğra – Küçük Ağa"], 'C',
      "Çalıkuşu Reşat Nuri Güntekin'in romanıdır. Oğuz Atay “Tutunamayanlar” ve “Tehlikeli Oyunlar” romanlarıyla tanınır."),
  _q('ss-164', 's11-edb-06', 'Biyografi', _k, "Tanınmış bir kişinin hayatının bir başkası tarafından anlatıldığı yazı türü hangisidir?",
      ["Otobiyografi", "Anı", "Günlük", "Biyografi", "Deneme"], 'D',
      "Biyografi (yaşam öyküsü) üçüncü kişi ağzından, belgelere dayanılarak ve nesnel bir tutumla yazılır."),
  _q('ss-165', 's11-edb-06', 'Tezkire', _k, "Divan edebiyatında şairlerin hayatları ve eserleri hakkında bilgi veren eserlere ne ad verilir?",
      ["Siyer", "Menakıbname", "Surname", "Gazavatname", "Tezkire (şuara tezkiresi)"], 'E',
      "Şuara tezkireleri, günümüzdeki biyografi ve edebiyat tarihi kitaplarının işlevini gören eserlerdir."),
  _q('ss-166', 's11-edb-06', 'Tezkire', _o, "Türk edebiyatında tezkire türünün ilk örneği sayılan “Mecâlisü'n-Nefâis” kime aittir?",
