  _q('ss-167', 's11-edb-06', 'Biyografi', _o, "İyi bir biyografi için aşağıdakilerden hangisi söylenemez?",
      ["Yazar, anlattığı kişiyi olduğundan üstün göstermek için bilgi uydurabilir.", "Belge ve tanıklıklara dayanmalıdır.", "Kronolojik bir sıra izleyebilir.", "Kişinin eserlerine ve dönemine yer verilir.", "Nesnel bir anlatım benimsenir."], 'A',
      "Biyografide gerçeklere bağlı kalınır; kişi övülmek ya da yerilmek için çarpıtılmaz."),
  _q('ss-168', 's11-edb-07', 'Modern Tiyatro', _k, "Şinasi'nin 1860'ta yayımladığı, Batılı anlamdaki ilk Türk tiyatro eseri sayılan tek perdelik töre komedisi hangisidir?",
