  _q('ss-178', 's11-tar-02', 'Lale Devri', _k, "Osmanlı Devleti'nde ilk Türk matbaası hangi dönemde kurulmuştur?",
      ["Tanzimat Dönemi", "Kanuni Dönemi", "Lale Devri", "Nizam-ı Cedid Dönemi", "I. Meşrutiyet Dönemi"], 'C',
      "İlk Türk matbaası Lale Devri'nde (1727) İbrahim Müteferrika ve Sait Mehmet Efendi tarafından kurulmuştur."),
  _q('ss-179', 's11-tar-03', 'Sanayi Devrimi', _k, "Sanayi Devrimi ilk olarak hangi ülkede başlamıştır?",
      ["Fransa", "Almanya", "Amerika Birleşik Devletleri", "İngiltere", "Rusya"], 'D',
      "Sanayi Devrimi 18. yüzyılın ikinci yarısında İngiltere'de buhar gücünün dokuma sanayisinde kullanılmasıyla başlamıştır."),
  _q('ss-180', 's11-tar-03', 'Sanayi Devrimi', _o, "Sanayi Devrimi'nin sonuçlarından biri aşağıdakilerden hangisi değildir?",
      ["Ham madde ve pazar arayışının artması", "İşçi sınıfının ortaya çıkması", "Köyden kente göçün hızlanması", "Sömürgecilik yarışının şiddetlenmesi", "El tezgâhlarının ve küçük atölyelerin güçlenmesi"], 'E',
      "Fabrika üretimi karşısında el tezgâhları rekabet edememiş ve gerilemiştir. Diğer seçenekler devrimin sonuçlarıdır."),
  _q('ss-181', 's11-tar-03', 'Sanayi Devrimi', _o, "Sanayi Devrimi'nin Osmanlı ekonomisine etkisi aşağıdakilerden hangisidir?",
      ["Osmanlı sanayisinin hızla gelişmesi", "Osmanlı'nın Avrupa'nın ham madde kaynağı ve pazarı hâline gelmesi", "Kapitülasyonların kaldırılması", "Dış borçlanmanın sona ermesi", "Lonca teşkilatının güçlenmesi"], 'B',
      "Ucuz Avrupa malları Osmanlı pazarını doldurmuş; yerli üretim rekabet edemeyip gerilemiş, Osmanlı ham madde ihraç eden bir pazar durumuna düşmüştür."),
  _q('ss-182', 's11-tar-03', 'Sanayi Devrimi', _z, "1838 Balta Limanı Ticaret Antlaşması'nın Osmanlı ekonomisine etkisi aşağıdakilerden hangisidir?",
      ["Yerli sanayinin dış rekabet karşısında korumasız kalması", "Gümrük gelirlerinin artması", "Yabancı tüccarların ülkeden çıkarılması", "Tekel (yed-i vahit) sisteminin güçlenmesi", "Osmanlı'nın sanayi devrimini gerçekleştirmesi"], 'A',
      "Antlaşmayla İngiliz tüccarlara büyük ayrıcalıklar tanınmış, tekel sistemi kaldırılmış; düşük gümrüklerle giren mallar yerli üretimi çökertmiştir."),
  _q('ss-183', 's11-tar-04', 'Fransız İhtilali', _k, "1789 Fransız İhtilali'nin yaydığı düşüncelerden hangisi çok uluslu imparatorlukların parçalanmasında en etkili olmuştur?",
      ["Eşitlik", "Adalet", "Milliyetçilik", "Özgürlük", "Laiklik"], 'C',
      "Her milletin kendi devletini kurma hakkı olduğunu savunan milliyetçilik akımı; Osmanlı, Avusturya-Macaristan ve Rusya gibi imparatorlukları sarsmıştır."),
  _q('ss-184', 's11-tar-04', 'Fransız İhtilali', _o, "Milliyetçilik akımının etkisiyle Osmanlı Devleti'nde ilk isyan eden ve ilk bağımsız olan milletler sırasıyla hangileridir?",
      ["Yunanlar – Sırplar", "Bulgarlar – Yunanlar", "Sırplar – Bulgarlar", "Sırplar – Yunanlar", "Arnavutlar – Sırplar"], 'D',
      "İlk isyan 1804'te Sırplar tarafından başlatılmış; ilk bağımsızlığını kazanan ise 1829 Edirne Antlaşması ile Yunanistan olmuştur."),
  _q('ss-185', 's11-tar-04', 'Fransız İhtilali', _o, "Fransız İhtilali'nin evrensel sonuçlarından biri aşağıdakilerden hangisi değildir?",
      ["Mutlak krallıkların sarsılması", "İnsan hakları düşüncesinin yayılması", "Milliyetçilik akımının güçlenmesi", "Demokrasi ve anayasa hareketlerinin hızlanması", "Feodal düzenin ve soyluların ayrıcalıklarının güçlenmesi"], 'E',
      "İhtilal soyluların ayrıcalıklarına son vermiş; eşitlik, özgürlük ve halk egemenliği düşüncelerini yaymıştır."),
  _q('ss-186', 's11-tar-04', 'İhtilale Tepkiler', _z, "1815 Viyana Kongresi'nin toplanma amacı aşağıdakilerden hangisidir?",
      ["Osmanlı topraklarını paylaşmak", "Napolyon savaşları sonrasında Avrupa'nın siyasi düzenini yeniden kurmak ve ihtilal fikirlerinin yayılmasını önlemek", "Sanayi Devrimi'ni başlatmak", "Milliyetçiliği desteklemek", "Sömürgeleri bağımsızlığına kavuşturmak"], 'B',
      "Kongrede krallıklar eski düzeni (restorasyon) korumaya çalışmış; ancak 1830 ve 1848 ihtilalleri bu düzeni sarsmıştır."),
  _q('ss-187', 's11-tar-06', 'Eğitim', _k, "Osmanlı Devleti'nde Avrupa tarzında açılan ilk teknik okul aşağıdakilerden hangisidir?",
      ["Mühendishane-i Bahrî-i Hümayun", "Darülfünun", "Mekteb-i Harbiye", "Mekteb-i Mülkiye", "Galatasaray Sultanisi"], 'A',
      "1773'te III. Mustafa döneminde açılan Mühendishane-i Bahrî-i Hümayun (deniz mühendishanesi) ilk Batılı teknik okuldur."),
  _q('ss-188', 's11-tar-06', 'Sanayileşme', _o, "Osmanlı Devleti'nde 19. yüzyılda sanayileşme çabalarının başarısız olmasının nedenlerinden biri aşağıdakilerden hangisi değildir?",
      ["Kapitülasyonlar ve düşük gümrük vergileri", "Sermaye yetersizliği", "Ham madde kaynaklarının hiç bulunmaması", "Teknik bilgi ve uzman eksikliği", "Avrupa mallarıyla rekabet edilememesi"], 'C',
      "Osmanlı ülkesi ham madde bakımından zengindi; sorun sermaye, teknoloji, uzman eksikliği ve dış rekabetti."),
  _q('ss-189', 's11-tar-06', 'Bilim ve Teknoloji', _o, "Osmanlı Devleti'nde ilk demir yolu hattı ve telgraf hangi yüzyılda kullanılmaya başlanmıştır?",
      ["16. yüzyıl", "17. yüzyıl", "18. yüzyıl", "19. yüzyıl", "20. yüzyıl"], 'D',
      "Telgraf Kırım Savaşı sırasında (1855) kullanılmaya başlanmış; ilk demir yolu hatları da 19. yüzyılın ikinci yarısında açılmıştır."),
  _q('ss-190', 's11-tar-06', 'Sanat', _o, "19. yüzyılda Batı tarzı resim ve müzecilik alanındaki çalışmalarıyla tanınan, Sanayi-i Nefise Mektebi'ni kuran Osmanlı sanatçısı kimdir?",
      ["Levnî", "Matrakçı Nasuh", "Mimar Kemaleddin", "Şeker Ahmet Paşa", "Osman Hamdi Bey"], 'E',
      "Osman Hamdi Bey ressam, arkeolog ve müzecidir; İstanbul Arkeoloji Müzesi'ni ve güzel sanatlar okulunu (Sanayi-i Nefise) kurmuştur."),
  _q('ss-191', 's11-tar-08', 'Göçler', _k, "Balkan Savaşları sonrasında Osmanlı Devleti'nde yaşanan en önemli toplumsal sorun aşağıdakilerden hangisidir?",
      ["Nüfusun azalması nedeniyle iş gücü fazlası", "Balkanlardan Anadolu'ya yapılan kitlesel Türk ve Müslüman göçleri", "Sanayinin aşırı gelişmesi", "Şehirlerin boşalması", "Tarım arazilerinin azalması"], 'B',
      "Balkan Savaşları'nda kaybedilen topraklardan yüz binlerce Türk ve Müslüman Anadolu'ya göç etmek zorunda kalmış; iskân ve geçim sorunları yaşanmıştır."),
  _q('ss-192', 's11-tar-08', 'Salgınlar', _o, "I. Dünya Savaşı yıllarında cephelerde ve cephe gerisinde can kayıplarını artıran etkenlerden biri aşağıdakilerden hangisidir?",
      ["Tifüs, kolera gibi salgın hastalıklar", "Nüfus artışı", "Sanayileşme", "Okuryazarlığın artması", "Ticaretin gelişmesi"], 'A',
      "Olumsuz koşullar, kıtlık ve yetersiz sağlık hizmetleri nedeniyle tifüs, kolera ve sıtma gibi salgınlar savaş kadar can kaybına yol açmıştır."),
  _q('ss-193', 's11-tar-08', 'Osmanlı Mirası', _o, "Osmanlı Devleti'nin insanlık tarihine katkıları arasında aşağıdakilerden hangisi gösterilebilir?",
