  _q('ss-230', 's11-fel-03', 'Akıl-İnanç İlişkisi', _o, "Akıl ile inancın birbiriyle çelişmediğini, felsefe ile dinin uzlaştırılabileceğini savunan İslam filozofu aşağıdakilerden hangisidir?",
      ["Epikür", "Nietzsche", "David Hume", "Sartre", "İbn Rüşd"], 'E',
      "İbn Rüşd, “Faslü'l-Makâl” adlı eserinde felsefe ile dinin aynı hakikate farklı yollardan ulaştığını savunmuştur. Farabi ve İbn Sina da akıl-vahiy uyumunu savunmuştur."),
  _q('ss-231', 's11-fel-04', 'Edebiyat-Felsefe İlişkisi', _k, "Felsefe ile edebiyatın ortak yönü aşağıdakilerden hangisidir?",
      ["İkisinin de deney yöntemini kullanması", "İkisinin de insanı, hayatı ve anlamı sorgulaması", "İkisinin de kesin sonuçlara ulaşması", "İkisinin de yalnızca kurmaca olması", "İkisinin de matematiksel dil kullanması"], 'B',
      "Her iki alan da insanın varoluşunu, değerlerini ve hayatın anlamını ele alır; felsefe kavramlarla, edebiyat imge ve kurguyla düşünür."),
  _q('ss-232', 's11-fel-04', 'Edebiyat-Felsefe İlişkisi', _o, "Varoluşçu felsefenin görüşlerini “Bulantı” romanı ve tiyatro oyunlarıyla da işleyen filozof-yazar kimdir?",
      ["Jean-Paul Sartre", "Immanuel Kant", "René Descartes", "John Locke", "Aristoteles"], 'A',
      "Sartre, varoluşçuluğu hem felsefi eserlerinde hem de “Bulantı”, “Duvar” ve “Sinekler” gibi edebî eserlerinde işlemiştir."),
  _q('ss-233', 's11-fel-04', 'Edebiyat-Felsefe İlişkisi', _o, "İbn Tufeyl'in “Hay bin Yakzan” adlı eseri felsefe–edebiyat ilişkisi açısından neden önemlidir?",
      ["İlk gezi yazısı olması", "İlk şiir kitabı olması", "Felsefi düşüncelerin bir hikâye (felsefi roman) biçiminde anlatılması", "İlk sözlük olması", "İlk tarih kitabı olması"], 'C',
      "Eser, ıssız bir adada tek başına büyüyen Hay'ın akıl ve gözlemle hakikate ulaşmasını anlatır; felsefi romanın ilk örneklerinden sayılır."),
  _q('ss-234', 's11-fel-04', 'Edebiyat-Felsefe İlişkisi', _z, "“Felsefe yapmak için edebî unsurlardan yararlanma”ya aşağıdakilerden hangisi örnek gösterilebilir?",
      ["Bir romanın sayfa sayısının artırılması", "Bir şiirde uyak kullanılması", "Bir hikâyenin kısaltılması", "Platon'un düşüncelerini diyaloglar ve mağara benzetmesiyle anlatması", "Bir makalenin dipnotlarla desteklenmesi"], 'D',
      "Platon felsefesini diyalog biçiminde yazmış; mağara benzetmesi (alegorisi) gibi edebî anlatımlarla soyut düşünceleri somutlaştırmıştır."),
  _q('ss-235', 's11-fel-05', 'Mutluluk ve Hayat', _k, "Mutluluğu hayatın en yüksek amacı olarak gören ahlak anlayışına ne ad verilir?",
      ["Nihilizm", "Stoacılık", "Kinizm", "Septisizm", "Eudaimonizm (mutluluk ahlakı)"], 'E',
      "Eudaimonizm, insan eylemlerinin nihai amacının mutluluk olduğunu savunur; Aristoteles'e göre mutluluk erdemli yaşamla kazanılır."),
  _q('ss-236', 's11-fel-05', 'Varoluş', _o, "“Varoluş özden önce gelir.” düşüncesi aşağıdaki görüşlerden hangisini ifade eder?",
      ["İnsanın kaderi doğmadan önce belirlenmiştir.", "İnsan önce var olur, kim olacağını kendi seçimleriyle belirler.", "İnsanın özü değişmezdir.", "Bilgi doğuştan gelir.", "Mutluluk hazda bulunur."], 'B',
      "Sartre'a göre insanın önceden belirlenmiş bir özü yoktur; insan özgür seçimleriyle kendini kurar ve bu seçimlerin sorumluluğunu taşır."),
  _q('ss-237', 's11-fel-05', 'Hayatın Anlamı', _z, "Hayatın anlamsızlığı (absürt) karşısında insanın yine de yaşamı sahiplenmesi gerektiğini “Sisifos Söyleni” adlı eserinde savunan düşünür kimdir?",
      ["Albert Camus", "Platon", "Thomas Hobbes", "Auguste Comte", "Francis Bacon"], 'A',
      "Camus'ye göre insan, anlam arayışı ile dünyanın sessizliği arasındaki uyumsuzluğun (absürt) bilincine vararak başkaldırmalı ve yaşamı sahiplenmelidir."),
  _q('ss-238', 's11-fel-06', 'Hukuk ve İnsan', _k, "Toplum düzenini sağlamak amacıyla konulan ve devlet gücüyle desteklenen kurallar bütününe ne ad verilir?",
      ["Görgü kuralları", "Örf ve âdet", "Hukuk", "Moda", "Gelenek"], 'C',
      "Hukuk kurallarını diğer toplumsal kurallardan ayıran özellik, uyulmadığında devletin yaptırım uygulamasıdır."),
  _q('ss-239', 's11-fel-06', 'Hukukun Kaynağı', _o, "İnsanın doğuştan sahip olduğu, devletten ve yasalardan önce var olan haklar bulunduğunu savunan anlayış hangisidir?",
      ["Pozitif hukuk", "Hukuki pragmatizm", "Tarihçi hukuk okulu", "Doğal hukuk", "Hukuki realizm"], 'D',
      "Doğal hukuk anlayışına göre yaşam, özgürlük gibi haklar insanın doğasından gelir; pozitif hukuk ise yürürlükteki yazılı kuralları esas alır."),
  _q('ss-240', 's11-fel-06', 'Hukukun Kaynağı', _o, "Bir ülkede belirli bir zamanda yürürlükte olan, yetkili organlarca konulmuş hukuk kurallarının tümüne ne ad verilir?",
      ["Doğal hukuk", "İdeal hukuk", "Ahlak", "Töre", "Pozitif hukuk"], 'E',
      "Pozitif hukuk yürürlükteki (mevzuat) hukuktur; anayasa, kanun ve yönetmelik gibi yazılı kurallardan oluşur."),
  _q('ss-241', 's11-fel-06', 'Ahlak-Hukuk İlişkisi', _z, "Ahlak kuralları ile hukuk kuralları arasındaki temel fark aşağıdakilerden hangisidir?",
      ["Ahlak kuralları yazılıdır, hukuk kuralları yazılı değildir.", "Hukuk kurallarının yaptırımı devlet gücüyle, ahlak kurallarının yaptırımı vicdan ve toplumsal tepkiyle sağlanır.", "Ahlak kuralları yalnızca yetişkinler içindir.", "Hukuk kuralları hiçbir zaman değişmez.", "Ahlak kuralları yalnızca aile içinde geçerlidir."], 'B',
      "Hukuka aykırı davranış maddi yaptırımla (ceza, tazminat) karşılaşır; ahlaka aykırı davranışın yaptırımı ise vicdan azabı ve toplumun kınamasıdır."),
  _q('ss-242', 's11-fel-03', 'Akıl-İnanç İlişkisi', _k, "Vahiy ile bildirilenlerin akılla kavranabileceğini, akıl ile inancın birbirini tamamladığını savunan yaklaşım için aşağıdakilerden hangisi söylenebilir?",
      ["İnancı tümüyle reddeder.", "Aklı tümüyle reddeder.", "Bilginin imkânsız olduğunu savunur.", "Yalnızca deneyi ölçüt alır.", "Akıl ile inancı uzlaştırmaya çalışır."], 'E',
      "Farabi, İbn Sina ve İbn Rüşd gibi filozoflar ile Aquinolu Thomas, akıl ve inancın çelişmediğini, birbirini tamamladığını savunmuştur."),
  _q('ss-243', 's11-fel-03', 'Akıl-İnanç İlişkisi', _o, "“Anlamak için inanıyorum.” sözüyle inancı bilginin ön koşulu sayan Orta Çağ düşünürü aşağıdakilerden hangisidir?",
      ["Epikuros", "David Hume", "Karl Marx", "Friedrich Nietzsche", "Augustinus"], 'E',
      "Augustinus'a (ve ardından Anselmus'a) göre inanç, hakikati kavramanın ilk adımıdır; akıl inancın ışığında anlamaya çalışır."),
  _q('ss-244', 's11-fel-01', 'Çevre ve İnsan', _k, "Çevre sorunlarının felsefenin konusu olmasının temel nedeni aşağıdakilerden hangisidir?",
      ["Felsefenin deney yapması", "Çevre sorunlarının yalnızca teknik bir konu olması", "Felsefenin doğa bilimlerinin yerini alması", "Çevre kirliliğinin ölçülememesi", "İnsanın doğa karşısındaki sorumluluğu ve değer yargılarını sorgulamayı gerektirmesi"], 'E',
      "Çevre sorunları yalnızca teknik değil, aynı zamanda etik bir konudur: insanın doğayla ilişkisi, sorumluluğu ve hakları sorgulanır."),
  _q('ss-245', 's11-fel-05', 'Hayatın Anlamı', _o, "“Sorgulanmamış hayat yaşanmaya değmez.” sözüyle hayatın anlamını insanın kendini bilmesinde ve erdemde arayan filozof kimdir?",
      ["Thomas Hobbes", "Epikuros", "Aristippos", "Protagoras", "Sokrates"], 'E',
      "Sokrates'e göre insan kendini tanımalı, yaşamını ve değerlerini sürekli sorgulamalıdır; erdem bilgidir ve mutluluğa erdemle ulaşılır."),
  _q('ss-246', 's10-cog-02', 'Volkanizma', _k, "Yer kabuğunun derinliklerindeki magmanın yeryüzüne çıkması olayına ne ad verilir?",
      ["Erozyon", "Heyelan", "Deprem", "Karstlaşma", "Volkanizma"], 'E',
      "Volkanizma, magmanın yer kabuğunun zayıf noktalarından yeryüzüne çıkmasıdır; levha sınırlarında yaygındır."),
  _q('ss-247', 's10-cog-03', 'Dış Kuvvetler', _o, "Türkiye'de yer şekillerinin oluşumunda en etkili dış kuvvet aşağıdakilerden hangisidir?",
      ["Rüzgârlar", "Buzullar", "Dalgalar", "Yer altı suları", "Akarsular"], 'E',
      "Türkiye'de yükselti ve eğim fazla, yağış rejimi düzensiz olduğundan akarsuların aşındırma ve biriktirme etkisi çok güçlüdür."),
